/* ===== Chemistry 0620 practical investigations (own wording). Entries follow the shared practical schema. ===== */
/* ---------- apparatus figure helpers (prefix PC_) ---------- */
const PC_FG=(vb,inner,cap,label,maxw)=>`<figure class="fig"${maxw?` style="max-width:${maxw}px"`:""}><svg viewBox="${vb}" role="img" aria-label="${label}">${inner}</svg><figcaption>${cap}</figcaption></figure>`;
const PC_T=(x,y,s,o)=>{o=o||{};return `<text x="${x}" y="${y}" font-size="${o.s||11}" text-anchor="${o.a||"start"}"${o.b?' font-weight="700"':""}${o.i?' font-style="italic"':""} fill="currentColor">${s}</text>`};
const PC_L=(x1,y1,x2,y2,w,o)=>`<path d="M${x1} ${y1}L${x2} ${y2}" stroke="currentColor" stroke-width="${w||1.5}" fill="none" stroke-linecap="round"${o?` ${o}`:""}/>`;
const PC_GL=(d,fill)=>`<path d="${d}" fill="${fill||"none"}" stroke="currentColor" stroke-opacity=".8" stroke-width="1.6" stroke-linejoin="round"/>`;
const PC_LQ=(d,op)=>`<path d="${d}" style="fill:var(--accent)" fill-opacity="${op||.3}" stroke="none"/>`;
const PC_LEAD=(x1,y1,x2,y2)=>`<path d="M${x1} ${y1}L${x2} ${y2}" stroke="currentColor" stroke-opacity=".55" stroke-width="1" fill="none"/>`;
const PC_RECT=(x,y,w,h,o)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${(o&&o.r)||2}" fill="${(o&&o.f)||"none"}"${o&&o.fs?` style="fill:${o.fs}"`:""} fill-opacity="${(o&&o.fo)||1}" stroke="currentColor" stroke-opacity="${(o&&o.so)||.8}" stroke-width="${(o&&o.w)||1.6}"/>`;
const PC_FLAME=(x,y,s)=>`<path d="M${x} ${y}c${-9*s} ${-10*s} ${-7*s} ${-20*s} 0 ${-30*s}c${7*s} ${10*s} ${9*s} ${20*s} 0 ${30*s}z" fill="#F2A93B" stroke="#D9482B" stroke-width="1.2"/>`;
const PC_STAND=(x,top,bot)=>PC_RECT(x-3,top,6,bot-top,{fs:"var(--mint)",so:.5,w:1.2})+PC_RECT(x-26,bot,70,6,{fs:"var(--mint)",so:.5,w:1.2});

