function PC_ARR_PC(x1,y1,x2,y2){const a=Math.atan2(y2-y1,x2-x1),h=6;return `<path d="M${x1} ${y1}L${x2} ${y2}M${x2} ${y2}l${(-h*Math.cos(a-.45)).toFixed(1)} ${(-h*Math.sin(a-.45)).toFixed(1)}M${x2} ${y2}l${(-h*Math.cos(a+.45)).toFixed(1)} ${(-h*Math.sin(a+.45)).toFixed(1)}" stroke="currentColor" stroke-width="1.6" fill="none" stroke-linecap="round" stroke-opacity=".7"/>`}

